package com.singtel.platformcommon;
import org.springframework.context.annotation.*;import org.springframework.web.client.RestClient;import org.springframework.http.client.JdkClientHttpRequestFactory;import java.net.http.HttpClient;import java.time.Duration;import org.springframework.web.context.request.*;
@Configuration public class Clients{@Bean public RestClient restClient(){var factory=new JdkClientHttpRequestFactory(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build());factory.setReadTimeout(Duration.ofSeconds(3));return RestClient.builder().requestFactory(factory).requestInterceptor((req,body,execution)->{var context=RequestContextHolder.getRequestAttributes();if(context instanceof ServletRequestAttributes a){for(String header:java.util.List.of("Authorization","X-Correlation-ID","X-Demo-Role")){String value=a.getRequest().getHeader(header);if(value!=null)req.getHeaders().set(header,value);}}return execution.execute(req,body);}).build();}}
